'use client';
import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { supabaseClient } from '@/lib/supabaseClient';
import CreateButton from '@/components/CreateButton';
import NewsCard from '../components/NewsCard';
import { News } from '../types';
import { Image as ImageIcon, FileText, LayoutGrid } from 'lucide-react';

export default function AdminNewsPage() {
  const [news, setNews] = useState<News[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchNews = async () => {
    setLoading(true);
    const { data, error } = await supabaseClient
      .from('news')
      .select('*')
      .order('created_at', { ascending: false });
    
    if (error) {
      console.error(error);
    } else {
      setNews((data as News[]) || []);
    }
    setLoading(false);
  };

  useEffect(() => { fetchNews(); }, []);

  const handleDelete = async (id: string) => {
    if (!confirm('Permanently remove this article from the database?')) return;
    try {
      const res = await fetch('http://localhost:5001/api/news/' + id, {
        method: 'DELETE',
        credentials: 'include',
      });
      if (res.ok) { setNews(news.filter((n) => n.id !== id)); }
    } catch (error) { alert('An error occurred while deleting.'); }
  };

  const handleTogglePublish = async (id: string, currentState: boolean) => {
    try {
      const res = await fetch('http://localhost:5001/api/news/' + id, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ published: !currentState }),
        credentials: 'include',
      });
      if (res.ok) {
        setNews(news.map((n) => n.id === id ? { ...n, published: !currentState } : n));
      }
    } catch (error) { console.error(error); }
  };

  return (
    <div className="min-h-screen bg-[#020617] text-white p-8 italic">
      <div className="max-w-5xl mx-auto space-y-10">
        
        {/* HEADER SECTION */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 border-b border-slate-800/50 pb-10">
          <header>
            <div className="flex items-center gap-2 mb-2">
              <LayoutGrid size={16} className="text-red-600" />
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Content Management</span>
            </div>
            <h1 className="text-5xl font-black uppercase tracking-tighter">
              News <span className="text-red-600">Archive</span>
            </h1>
          </header>
          
          <div className="flex items-center gap-6">
            <div className="text-right hidden md:block">
              <p className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Total Stories</p>
              <p className="text-2xl font-black text-white">{news.length}</p>
            </div>
            <Link href="/admin/news/new">
              <CreateButton>Create New Entry</CreateButton>
            </Link>
          </div>
        </div>

        {/* DATA GRID */}
        <div className="grid grid-cols-1 gap-4">
          {loading ? (
            <div className="py-20 text-center animate-pulse">
              <p className="text-slate-500 font-black uppercase tracking-widest text-xs">Accessing Database...</p>
            </div>
          ) : news.length > 0 ? (
            news.map((item) => (
              <NewsCard
                key={item.id}
                news={item}
                onDelete={() => handleDelete(item.id)}
                onTogglePublish={() => handleTogglePublish(item.id, item.published)}
              />
            ))
          ) : (
            <div className="py-20 text-center border-2 border-dashed border-slate-800 rounded-[2rem]">
               <FileText className="mx-auto text-slate-800 mb-4" size={40} />
               <p className="text-slate-600 font-black uppercase tracking-widest text-xs">No articles found in archive</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}